// Fetch recent FERC notices from Federal Register API and classify as EPC signals.
// No API key required. Replaces the dead FERC EFTS (efts.ferc.gov) endpoint.
// Federal Register API docs: https://www.federalregister.gov/reader-aids/developer-resources/rest-api

const LOOKBACK_DAYS = 7;
const PER_PAGE = 50;
const BASE_URL = 'https://www.federalregister.gov/api/v1/articles.json';

const SIGNAL_RULES = [
  { score: 20, label: 'Interconnection Agreement', keywords: [
    'interconnection agreement', 'generator interconnection',
    'transmission interconnection', 'large generator interconnection',
    'small generator interconnection'
  ]},
  { score: 18, label: 'PPA / Storage Interconnection', keywords: [
    'power purchase agreement', ' ppa ', 'energy storage interconnection',
    'battery storage', 'pumped storage'
  ]},
  { score: 15, label: 'Transmission Construction', keywords: [
    'transmission line', 'transmission project', 'transmission upgrade',
    'transmission expansion', 'transmission facility', 'new transmission',
    'overhead line', 'underground cable', 'substation construction'
  ]},
  { score: 12, label: 'Rate Case / IRP', keywords: [
    'rate case', 'rate schedule', 'integrated resource plan', ' irp ',
    'cost of service', 'wholesale rate'
  ]},
  { score: 10, label: 'Hydro License', keywords: [
    'hydroelectric', 'hydro license', 'relicensing', 'water power license'
  ]}
];

const BONUS_TERMS = {
  'billion': 10, '765 kv': 8, '500 kv': 8, '345 kv': 5,
  'hvdc': 8, 'high voltage': 5, 'data center': 5, 'datacenter': 5,
  'hyperscale': 5, 'nuclear': 5, ' smr ': 5, 'solar': 3,
  'wind': 3, 'gigawatt': 5, ' gw ': 3, ' mw ': 2
};

const SKIP_KEYWORDS = [
  'comment request', 'paperwork reduction', 'information collection',
  'omb review', 'notice of filing', 'delegation of authority',
  'sunshine act', 'closed meeting', 'open meeting'
];

function classify(title, abstract) {
  const text = (title + ' ' + (abstract || '')).toLowerCase();
  if (SKIP_KEYWORDS.some(kw => text.includes(kw))) return null;
  for (const rule of SIGNAL_RULES) {
    if (rule.keywords.some(kw => text.includes(kw))) {
      return { score: rule.score, label: rule.label };
    }
  }
  return null;
}

function boostScore(base, title, abstract) {
  const text = (title + ' ' + (abstract || '')).toLowerCase();
  let score = base;
  for (const [term, bonus] of Object.entries(BONUS_TERMS)) {
    if (text.includes(term)) score += bonus;
  }
  const dollarHits = (text.match(/\$[\d,.]+\s?(?:billion|million)/gi) || []).length;
  score += dollarHits * 3;
  return Math.min(Math.round(score * 10) / 10, 100);
}

function extractCompany(title, abstract) {
  const semiMatch = title.match(/^([^;]+);/);
  if (semiMatch) {
    const candidate = semiMatch[1].trim();
    if (!['commission', 'ferc', 'notice', 'order'].some(w => candidate.toLowerCase().includes(w))) {
      return candidate;
    }
  }
  if (abstract) {
    const m = abstract.match(/\b([A-Z][a-zA-Z\s&,.]+(?:Inc|LLC|Corp|Company|Authority|Power|Energy|Electric|Utility|Co)\.?)\b/);
    if (m) return m[1].trim();
  }
  return 'FERC Filing';
}

function determineSector(title, abstract) {
  const text = (title + ' ' + (abstract || '')).toLowerCase();
  if (['nuclear', 'smr', 'uranium', 'reactor', 'atomic'].some(kw => text.includes(kw))) return 'Nuclear & Critical Minerals';
  if (['defense', 'military', 'dod', 'pentagon'].some(kw => text.includes(kw))) return 'Defense';
  if (['natural gas', 'lng', 'pipeline', 'gas transmission'].some(kw => text.includes(kw))) return 'Natural Gas Infrastructure';
  return 'Power & Grid Infrastructure';
}

const now = new Date();
const startDate = new Date(now - LOOKBACK_DAYS * 86400000);
const fmt = d => d.toISOString().slice(0, 10);

const signals = [];
const seenDocs = new Set();
let page = 1;
let totalPages = 1;

do {
  const url = BASE_URL + '?conditions%5Bagencies%5D%5B%5D=federal-energy-regulatory-commission'
    + '&conditions%5Bpublication_date%5D%5Bgte%5D=' + fmt(startDate)
    + '&conditions%5Bpublication_date%5D%5Blte%5D=' + fmt(now)
    + '&per_page=' + PER_PAGE + '&page=' + page
    + '&order=newest&fields%5B%5D=title&fields%5B%5D=publication_date'
    + '&fields%5B%5D=abstract&fields%5B%5D=document_number&fields%5B%5D=html_url';
  const resp = await this.helpers.httpRequest({ url, method: 'GET' });
  const results = resp.results || [];
  totalPages = resp.total_pages || 1;

  for (const article of results) {
    const docNum = article.document_number || '';
    if (seenDocs.has(docNum)) continue;
    seenDocs.add(docNum);
    const title = article.title || '';
    const abstract = article.abstract || '';
    const pubDate = article.publication_date || fmt(now);
    const htmlUrl = article.html_url || '';
    const cls = classify(title, abstract);
    if (!cls) continue;
    const heat = boostScore(cls.score, title, abstract);
    signals.push({
      signal_type: 'ferc_filing',
      source: 'ferc_efts',
      company_name: extractCompany(title, abstract),
      sector: determineSector(title, abstract),
      signal_date: pubDate,
      raw_text: 'FERC Notice: ' + title + '\nType: ' + cls.label + ' | Published: ' + pubDate + ' | Doc: ' + docNum + '\n' + abstract.slice(0, 800),
      heat_score: heat,
      url: htmlUrl,
      notes: cls.label + ' | Doc: ' + docNum,
      captured_at: new Date().toISOString()
    });
  }
  page++;
} while (page <= Math.min(totalPages, 3));

console.log('[FERC FR] ' + signals.length + ' signals from ' + seenDocs.size + ' articles');
if (!signals.length) return [{ json: { _skip: true, count: 0 } }];
return signals.map(s => ({ json: s }));
